-- Generated by scripts/ranking-storage/generate.py. LOCAL REHEARSAL REQUIRED.
-- Apply during the documented maintenance window, with a verified backup.
BEGIN;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '180s';
SELECT pg_advisory_xact_lock(hashtextextended('statsforspotify:maintenance-release',0));
LOCK TABLE public.snapshots IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public.album_rankings, public.artist_rankings, public.track_rankings IN ACCESS EXCLUSIVE MODE;
CREATE SCHEMA ranking_storage AUTHORIZATION postgres;
CREATE SCHEMA ranking_storage_backup AUTHORIZATION postgres;
REVOKE ALL ON SCHEMA ranking_storage, ranking_storage_backup FROM PUBLIC, anon, authenticated, service_role;
COMMENT ON SCHEMA ranking_storage_backup IS 'Empty original table definitions for lossless rollback; never expose through the Data API.';
COMMENT ON SCHEMA ranking_storage IS 'Private versioned ranking storage; clients use the public security-invoker views.';

-- A definer trigger cannot use current_user to identify its caller. SET ROLE is
-- permission-checked by PostgreSQL, unlike user-editable JWT metadata.
CREATE FUNCTION ranking_storage.caller_bypasses_rls() RETURNS boolean
LANGUAGE sql STABLE SET search_path = pg_catalog, pg_temp AS $$
  SELECT coalesce((SELECT rolsuper OR rolbypassrls FROM pg_roles
    WHERE rolname = coalesce(nullif(current_setting('role',true),'none'),session_user)),false)
$$;
REVOKE ALL ON FUNCTION ranking_storage.caller_bypasses_rls() FROM PUBLIC;

-- Parent locks precede owner locks, so snapshot/account cascades cannot wait on
-- a writer that is itself waiting for those parents. Batches from the collectors
-- contain one owner/snapshot. Administrative imports must use that same boundary.
CREATE FUNCTION ranking_storage.lock_write(p_users uuid[], p_snapshots uuid[]) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE v_user uuid;
BEGIN
  PERFORM id FROM auth.users WHERE id=ANY(p_users) ORDER BY id FOR KEY SHARE;
  PERFORM id FROM public.snapshots WHERE id=ANY(p_snapshots) ORDER BY id FOR KEY SHARE;
  FOR v_user IN SELECT DISTINCT x FROM unnest(p_users) x WHERE x IS NOT NULL ORDER BY x LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('ranking-storage:'||v_user::text,0));
  END LOOP;
END $$;
REVOKE ALL ON FUNCTION ranking_storage.lock_write(uuid[],uuid[]) FROM PUBLIC;


