  IF md5(jsonb_build_object(
 'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON a.attrelid=d.adrelid AND a.attnum=d.adnum WHERE a.attrelid='public.artist_rankings'::regclass AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_array(c.contype,pg_get_constraintdef(c.oid),c.convalidated,c.condeferrable,c.condeferred) ORDER BY c.contype,pg_get_constraintdef(c.oid)) FROM pg_constraint c WHERE c.conrelid='public.artist_rankings'::regclass),
 'policies',(SELECT jsonb_agg(jsonb_build_array(p.polname,p.polcmd,p.polpermissive,(SELECT jsonb_agg(CASE WHEN x=0 THEN 'public' ELSE x::regrole::text END ORDER BY x::regrole::text) FROM unnest(p.polroles)x),pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY p.polname) FROM pg_policy p WHERE p.polrelid='public.artist_rankings'::regclass),
 'rls',(SELECT jsonb_build_array(relrowsecurity,relforcerowsecurity) FROM pg_class WHERE oid='public.artist_rankings'::regclass)
)::text) <> '2d6d7b0bc4db1ea932a2469ce26ac5c9' THEN
    RAISE EXCEPTION 'Source schema or policies changed: artist_rankings; re-audit before migrating';
  END IF;
  IF (SELECT relkind FROM pg_class WHERE oid='public.artist_rankings'::regclass) <> 'r'
    OR (SELECT array_agg(attname::text ORDER BY attnum) FROM pg_attribute
        WHERE attrelid='public.artist_rankings'::regclass AND attnum>0 AND NOT attisdropped) <> ARRAY['id', 'snapshot_id', 'user_id', 'artist_id', 'artist_name', 'artist_image_url', 'genres', 'popularity', 'rank', 'created_at', 'previous_rank']::text[]
    OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='public.artist_rankings'::regclass AND polcmd IN ('w','*'))
    OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.artist_rankings'::regclass AND NOT tgisinternal)
