ALTER TABLE public.artist_rankings SET SCHEMA ranking_storage_backup;

CREATE FUNCTION ranking_storage.artist_fingerprint(p_artist_id text, p_artist_name text, p_artist_image_url text, p_genres text[]) RETURNS bytea
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
 SELECT sha256(convert_to(jsonb_build_array(p_artist_id, p_artist_name, p_artist_image_url, p_genres, array_dims(p_genres))::text,'UTF8'))
$$;
REVOKE ALL ON FUNCTION ranking_storage.artist_fingerprint FROM PUBLIC;
ALTER FUNCTION ranking_storage.artist_fingerprint OWNER TO postgres;
CREATE TABLE ranking_storage.artist_metadata (
 metadata_key integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
 artist_id text NOT NULL, artist_name text NOT NULL, artist_image_url text, genres text[],
 metadata_hash bytea GENERATED ALWAYS AS (ranking_storage.artist_fingerprint(artist_id, artist_name, artist_image_url, genres)) STORED,
 collision integer NOT NULL DEFAULT 0,
 UNIQUE (metadata_key,user_id), UNIQUE (user_id,metadata_hash,collision)
);
CREATE INDEX ON ranking_storage.artist_metadata(user_id,artist_id);
CREATE TABLE ranking_storage.artist_observations (
 id uuid NOT NULL DEFAULT gen_random_uuid(),
 snapshot_id uuid NOT NULL REFERENCES public.snapshots(id) ON DELETE CASCADE,
 user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
 created_at timestamptz NOT NULL DEFAULT now(),
 metadata_key integer NOT NULL,
 popularity integer, rank integer NOT NULL CHECK (rank BETWEEN 1 AND 50), previous_rank integer,
 FOREIGN KEY(metadata_key,user_id) REFERENCES ranking_storage.artist_metadata(metadata_key,user_id)
);
ALTER TABLE ranking_storage.artist_metadata OWNER TO postgres;
ALTER TABLE ranking_storage.artist_observations OWNER TO postgres;

-- Distinct typed metadata preserves NULLs and PostgreSQL array bounds. A digest
-- only selects a bucket; collisions use another discriminator, never wrong data.
INSERT INTO ranking_storage.artist_metadata(user_id,artist_id, artist_name, artist_image_url, genres,collision)
 SELECT user_id,artist_id, artist_name, artist_image_url, genres,(row_number() OVER (PARTITION BY user_id,
 ranking_storage.artist_fingerprint(artist_id, artist_name, artist_image_url, genres))-1)::integer
 FROM (SELECT DISTINCT user_id,artist_id, artist_name, artist_image_url, genres FROM ranking_storage_backup.artist_rankings) d;
INSERT INTO ranking_storage.artist_observations(id, snapshot_id, user_id, created_at, metadata_key, popularity, rank, previous_rank)
 SELECT r.id, r.snapshot_id, r.user_id, r.created_at, m.metadata_key, r.popularity, r.rank, r.previous_rank
 FROM ranking_storage_backup.artist_rankings r JOIN ranking_storage.artist_metadata m
 ON m.user_id=r.user_id AND m.metadata_hash=ranking_storage.artist_fingerprint(r.artist_id, r.artist_name, r.artist_image_url, r.genres)
 AND m.artist_id IS NOT DISTINCT FROM r.artist_id AND m.artist_name IS NOT DISTINCT FROM r.artist_name AND m.artist_image_url IS NOT DISTINCT FROM r.artist_image_url AND m.genres IS NOT DISTINCT FROM r.genres;

-- Build narrow indexes after the bulk copy. Repeated snapshot/owner/metadata
-- keys can use B-tree deduplication; sorting one snapshot's 50 rows is cheap.
ALTER TABLE ranking_storage.artist_observations ADD PRIMARY KEY(id);
CREATE INDEX ON ranking_storage.artist_observations(snapshot_id);
CREATE INDEX ON ranking_storage.artist_observations(user_id);
CREATE INDEX ON ranking_storage.artist_observations(metadata_key);

ALTER TABLE ranking_storage.artist_metadata ENABLE ROW LEVEL SECURITY;
ALTER TABLE ranking_storage.artist_observations ENABLE ROW LEVEL SECURITY;
-- Preserve the exact live SELECT policies, including restrictive privacy rules.
DO $$ DECLARE p record; roles text; destination text;
BEGIN
 FOR p IN SELECT * FROM pg_policy WHERE polrelid='ranking_storage_backup.artist_rankings'::regclass AND polcmd='r' LOOP
  SELECT string_agg(CASE WHEN x=0 THEN 'PUBLIC' ELSE quote_ident(x::regrole::text) END,',') INTO roles FROM unnest(p.polroles) x;
  FOREACH destination IN ARRAY ARRAY['artist_metadata','artist_observations'] LOOP
   EXECUTE format('CREATE POLICY %I ON ranking_storage.%I AS %s FOR SELECT TO %s USING (%s)',p.polname,destination,
    CASE WHEN p.polpermissive THEN 'PERMISSIVE' ELSE 'RESTRICTIVE' END,roles,pg_get_expr(p.polqual,p.polrelid));
  END LOOP;
 END LOOP;
END $$;
CREATE VIEW public.artist_rankings WITH(security_invoker=true) AS
 SELECT o.id, o.snapshot_id, o.user_id, m.artist_id, m.artist_name, m.artist_image_url, m.genres, o.popularity, o.rank, o.created_at, o.previous_rank FROM ranking_storage.artist_observations o
 JOIN ranking_storage.artist_metadata m ON m.metadata_key=o.metadata_key AND m.user_id=o.user_id;
ALTER VIEW public.artist_rankings OWNER TO postgres;
GRANT SELECT ON ranking_storage.artist_metadata, ranking_storage.artist_observations TO anon,authenticated,service_role;
-- No schema USAGE or physical write grants to API roles. PostgreSQL resolves
-- the underlying view relations at creation; security-invoker RLS still applies.
DO $$ DECLARE d record; a record;
BEGIN
 FOR d IN SELECT attname,pg_get_expr(adbin,adrelid) AS expression FROM pg_attrdef JOIN pg_attribute
  ON adrelid=attrelid AND adnum=attnum WHERE adrelid='ranking_storage_backup.artist_rankings'::regclass LOOP
  EXECUTE format('ALTER VIEW public.artist_rankings ALTER COLUMN %I SET DEFAULT %s',d.attname,d.expression);
 END LOOP;
 FOR a IN SELECT x.* FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) x
  WHERE c.oid='ranking_storage_backup.artist_rankings'::regclass LOOP
  EXECUTE format('GRANT %s ON public.artist_rankings TO %s%s',a.privilege_type,
   CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(a.grantee::regrole::text) END,
   CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END);
 END LOOP;
END $$;

CREATE FUNCTION ranking_storage.write_artist() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE v_privileged boolean := ranking_storage.caller_bypasses_rls();
 v_metadata integer; v_hash bytea; v_collision integer; v_id uuid;
 v_current public.artist_rankings%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation') <> 'read committed' THEN
  RAISE EXCEPTION 'Ranking writes require READ COMMITTED isolation' USING ERRCODE='0A000';
 END IF;
 -- Match original INSERT/DELETE ownership and the absence of an UPDATE policy.
 IF NOT v_privileged THEN
  IF TG_OP='UPDATE' THEN RETURN NULL; END IF;
  IF TG_OP='DELETE' AND (auth.uid() IS NULL OR OLD.user_id IS DISTINCT FROM auth.uid()) THEN RETURN NULL; END IF;
  IF TG_OP='INSERT' AND (auth.uid() IS NULL OR NEW.user_id IS DISTINCT FROM auth.uid()) THEN
   RAISE EXCEPTION 'new row violates row-level security policy for artist_rankings' USING ERRCODE='42501';
  END IF;
 END IF;
 PERFORM ranking_storage.lock_write(
  ARRAY[CASE WHEN TG_OP<>'DELETE' THEN NEW.user_id END,CASE WHEN TG_OP<>'INSERT' THEN OLD.user_id END],
  ARRAY[CASE WHEN TG_OP<>'DELETE' THEN NEW.snapshot_id END,CASE WHEN TG_OP<>'INSERT' THEN OLD.snapshot_id END]);
 IF TG_OP IN ('DELETE','UPDATE') THEN
  SELECT o.id, o.snapshot_id, o.user_id, m.artist_id, m.artist_name, m.artist_image_url, m.genres, o.popularity, o.rank, o.created_at, o.previous_rank INTO v_current FROM ranking_storage.artist_observations o
   JOIN ranking_storage.artist_metadata m ON m.metadata_key=o.metadata_key AND m.user_id=o.user_id
   WHERE o.id=OLD.id FOR UPDATE OF o;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_current IS DISTINCT FROM OLD THEN
   RAISE EXCEPTION 'Ranking changed concurrently; retry transaction' USING ERRCODE='40001';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN
  DELETE FROM ranking_storage.artist_observations WHERE id=OLD.id RETURNING id INTO v_id;
  IF v_id IS NULL THEN RETURN NULL; END IF;
  RETURN OLD;
 END IF;
 v_hash := ranking_storage.artist_fingerprint(NEW.artist_id, NEW.artist_name, NEW.artist_image_url, NEW.genres);
 -- Separate statement after the lock gives a fresh READ COMMITTED snapshot.
 SELECT metadata_key INTO v_metadata FROM ranking_storage.artist_metadata m
 WHERE m.user_id=NEW.user_id AND m.metadata_hash=v_hash AND m.artist_id IS NOT DISTINCT FROM NEW.artist_id AND m.artist_name IS NOT DISTINCT FROM NEW.artist_name AND m.artist_image_url IS NOT DISTINCT FROM NEW.artist_image_url AND m.genres IS NOT DISTINCT FROM NEW.genres;
 IF v_metadata IS NULL THEN
  SELECT coalesce(max(collision)+1,0) INTO v_collision FROM ranking_storage.artist_metadata
   WHERE user_id=NEW.user_id AND metadata_hash=v_hash;
  BEGIN
   INSERT INTO ranking_storage.artist_metadata(user_id,artist_id, artist_name, artist_image_url, genres,collision)
   VALUES(NEW.user_id,NEW.artist_id, NEW.artist_name, NEW.artist_image_url, NEW.genres,v_collision) RETURNING metadata_key INTO v_metadata;
  EXCEPTION WHEN unique_violation THEN
   -- Fail atomically if a concurrent administrative writer bypasses this lock.
   RAISE EXCEPTION 'concurrent metadata change; retry transaction' USING ERRCODE='40001';
  END;
 END IF;
 IF TG_OP='INSERT' THEN
  INSERT INTO ranking_storage.artist_observations(id, snapshot_id, user_id, created_at, metadata_key, popularity, rank, previous_rank) VALUES(NEW.id, NEW.snapshot_id, NEW.user_id, NEW.created_at, v_metadata, NEW.popularity, NEW.rank, NEW.previous_rank);
 ELSE
  UPDATE ranking_storage.artist_observations SET id=NEW.id, snapshot_id=NEW.snapshot_id, user_id=NEW.user_id, created_at=NEW.created_at, metadata_key=v_metadata, popularity=NEW.popularity, rank=NEW.rank, previous_rank=NEW.previous_rank WHERE id=OLD.id RETURNING id INTO v_id;
  IF v_id IS NULL THEN RETURN NULL; END IF;
 END IF;
 RETURN NEW;
END $$;
ALTER FUNCTION ranking_storage.write_artist() OWNER TO postgres;
REVOKE ALL ON FUNCTION ranking_storage.write_artist() FROM PUBLIC;
CREATE TRIGGER write_artist_ranking INSTEAD OF INSERT OR UPDATE OR DELETE ON public.artist_rankings
 FOR EACH ROW EXECUTE FUNCTION ranking_storage.write_artist();

CREATE FUNCTION ranking_storage.prune_artist() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF current_setting('transaction_isolation') <> 'read committed' THEN
  RAISE EXCEPTION 'Ranking deletion requires READ COMMITTED isolation' USING ERRCODE='0A000';
 END IF;
 IF TG_OP='UPDATE' AND OLD.metadata_key=NEW.metadata_key AND OLD.user_id=NEW.user_id THEN RETURN NULL; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('ranking-storage:'||OLD.user_id::text,0));
 DELETE FROM ranking_storage.artist_metadata m WHERE m.metadata_key=OLD.metadata_key
 AND NOT EXISTS(SELECT 1 FROM ranking_storage.artist_observations o WHERE o.metadata_key=m.metadata_key);
 RETURN NULL;
END $$;
ALTER FUNCTION ranking_storage.prune_artist() OWNER TO postgres;
REVOKE ALL ON FUNCTION ranking_storage.prune_artist() FROM PUBLIC;
CREATE TRIGGER prune_artist_metadata AFTER DELETE OR UPDATE ON ranking_storage.artist_observations
 FOR EACH ROW EXECUTE FUNCTION ranking_storage.prune_artist();

DO $$ BEGIN
 IF EXISTS((SELECT * FROM ranking_storage_backup.artist_rankings EXCEPT ALL SELECT * FROM public.artist_rankings)
  UNION ALL (SELECT * FROM public.artist_rankings EXCEPT ALL SELECT * FROM ranking_storage_backup.artist_rankings))
 THEN RAISE EXCEPTION 'Exact reconstruction failed: artist_rankings'; END IF;
END $$;


