DO $$ BEGIN
 IF EXISTS((SELECT * FROM ranking_storage_backup.album_rankings EXCEPT ALL SELECT * FROM public.album_rankings)
  UNION ALL (SELECT * FROM public.album_rankings EXCEPT ALL SELECT * FROM ranking_storage_backup.album_rankings))
 THEN RAISE EXCEPTION 'Exact reconstruction failed: album_rankings'; END IF;
END $$;


